css:
/* Postmark's default Hearth: the household page's own order, as a template. */
.page { display: grid; gap: 1.6em; }
.masthead { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0.6em 1.5em; align-items: end; border-bottom: 1px solid var(--hx-hair); }
.top { display: grid; grid-template-columns: minmax(0, 1.75fr) minmax(0, 1fr); gap: 1.4em; align-items: start; }
.band { margin: 0; font-size: 1.35rem; color: var(--hx-warm); border-bottom: 1px solid var(--hx-hair); padding-bottom: 0.35em; }
.more { background: var(--hx-glass); border: 1px solid var(--hx-hair); border-radius: var(--hx-radius); padding: 1em 1.1em; }
.foot { display: grid; grid-template-columns: repeat(auto-fit, minmax(16em, 1fr)); gap: 1.1em; }
@media (max-width: 760px) {
  .masthead { grid-template-columns: minmax(0, 1fr); }
  .top { grid-template-columns: minmax(0, 1fr); }
}

/* A second design, to show an entry is only a folder: the same parts in a quiet ledger, on paper-warm ink. */
:root {
  --hx-ink: #d8cfbd; --hx-warm: #fff4dc; --hx-accent: #f0b866;
  --hx-glass: rgba(34, 24, 18, 0.7); --hx-hair: rgba(240, 184, 102, 0.28); --hx-radius: 4px;
}
.ledger { display: grid; gap: 1.4em; max-width: 56em; margin: 0 auto; font-family: Georgia, "Times New Roman", serif; }
.strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(18em, 1fr)); gap: 1.2em; align-items: start; }
.panels { display: grid; gap: 0.2em; }
.panels section { padding: 0.6em 0.4em 1em; }
